"use client";
import { uiText, getFormatLocale, useUiLocale } from "@/lib/locale";


import Link from "next/link";
import { useEffect, useRef, useState } from "react";
import { Activity, BarChart3, BookOpenText, CalendarClock, Check, CheckCircle2, ChevronLeft, CircleDollarSign, ClipboardList, CreditCard, ExternalLink, Gift, Globe2, HandCoins, ImageUp, KeyRound, Link2, LogIn, LogOut, Mail, MessageSquare, Package, Pencil, Plus, Save, Send, Settings2, Trash2, UserPlus, UserRound, UsersRound } from "lucide-react";
import { CartesianGrid, Legend, Line, LineChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import type { CoachClientDetail, CoachServiceOfferSummary, CoachWorkspaceResponse } from "@levelup/contracts";
import { coachApi, partnerPortalApi } from "@/lib/api";
import styles from "./coach.module.css";

type Tab = "overview"|"clients"|"scheduling"|"services"|"plans"|"site"|"telegram"|"rewards"|"profile";
type ClientSection = "state"|"insights"|"feedback"|"assignments";
function tabs() { return [
  ["overview",uiText("Обзор"),BarChart3],["clients",uiText("Клиенты"),UsersRound],["scheduling",uiText("Расписание"),CalendarClock],["services",uiText("Услуги"),HandCoins],["plans",uiText("Пакет"),Package],
  ["site",uiText("Сайт"),Globe2],["telegram","Telegram",MessageSquare],["rewards",uiText("Награды"),Gift],["profile",uiText("Профиль"),Settings2]
] as const; }
const makeKey=()=>typeof crypto!=="undefined"&&crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random()}`;

export default function CoachWorkspacePage(){
  useUiLocale();
  const [workspace,setWorkspace]=useState<CoachWorkspaceResponse|null>(null);
  const [tab,setTab]=useState<Tab>("overview");const [loading,setLoading]=useState(true);const [loginRequired,setLoginRequired]=useState(false);const [error,setError]=useState("");const [notice,setNotice]=useState("");const [logoutBusy,setLogoutBusy]=useState(false);
  const [checkoutPolls,setCheckoutPolls]=useState(0);
  const [selected,setSelected]=useState<CoachClientDetail|null>(null);
  const load=()=>{setLoading(true);setError("");coachApi.workspace().then((data)=>{setWorkspace(data);setLoginRequired(false);const queryReferral=new URLSearchParams(window.location.search).get("ref")?.trim();if(queryReferral)window.localStorage.setItem("orken_referral_code",queryReferral);const referral=queryReferral||window.localStorage.getItem("orken_referral_code");if(referral)void coachApi.captureAttribution(referral).catch(()=>undefined)}).catch((reason)=>{if(String(reason?.message||reason).toLowerCase().includes("login")){setLoginRequired(true)}else setError(reason instanceof Error?reason.message:uiText("Не удалось загрузить кабинет"))}).finally(()=>setLoading(false))};
  useEffect(load,[]);
  useEffect(()=>{if(!workspace)return;const status=new URLSearchParams(window.location.search).get("subscription");if(status==="cancelled"){setNotice(uiText("Оплата отменена. Пакет не подключён."));return}if(status!=="active")return;if(workspace.subscription){setNotice(uiText("Пакет подключён. Теперь можно приглашать клиентов за счёт пакета."));window.history.replaceState({},"","/coach");return}if(checkoutPolls>=4){setNotice(uiText("Платёж принят. Активация пакета ещё обрабатывается; обновите страницу через минуту."));return}setNotice(uiText("Платёж принят. Подтверждаем активацию пакета..."));const timer=window.setTimeout(()=>{setCheckoutPolls(value=>value+1);load()},2000*(checkoutPolls+1));return()=>window.clearTimeout(timer)},[workspace?.subscription,checkoutPolls]);
  useEffect(()=>{if(!workspace)return;const billing=new URLSearchParams(window.location.search).get("billing");if(billing!=="returned")return;setNotice(uiText("Настройки оплаты обновлены. Статус подписки синхронизируется со Stripe."));window.history.replaceState({},"","/coach")},[workspace]);
  async function logout(){setLogoutBusy(true);setError("");try{await partnerPortalApi.logout()}catch(reason){setError(reason instanceof Error?reason.message:uiText("Не удалось завершить сессию"))}finally{setWorkspace(null);setLoginRequired(true);setLogoutBusy(false)}}
  if(loading)return <main className={styles.page}><div className={styles.empty}>{uiText("Загружаем кабинет коуча...")}</div></main>;
  if(loginRequired)return <CoachLogin onDone={load}/>;
  if(!workspace)return <main className={styles.page}><div className={styles.error}>{error}</div></main>;
  const counts=workspace.counts;
  return <main className={styles.page}><div className={styles.shell}>
    <aside className={styles.sidebar}><Link className={styles.brand} href="/">ORKEN.LIFE</Link><nav>{tabs().map(([id,label,Icon])=><button key={id} className={tab===id?styles.active:""} onClick={()=>{setTab(id);setSelected(null)}}><Icon size={18}/>{label}</button>)}</nav><div className={styles.sidebarFoot}><Link className={styles.link} href="/partners"><Link2 size={15}/> {uiText(" Рефералы и финансы")}</Link><Link className={styles.link} href="/coaches">{uiText("Открыть каталог")}</Link></div></aside>
    <section className={styles.main}><header className={styles.top}><div><span className={styles.badge}>{uiText("Кабинет коуча")}</span><h1>{title(tab)}</h1><p>{description(tab)}</p></div><div className={styles.topActions}><span className={styles.status}>{statusLabel(workspace.profile.status)}</span><button className={styles.logoutButton} type="button" onClick={logout} disabled={logoutBusy}><LogOut size={16}/>{logoutBusy?uiText("Выходим..."):uiText("Выйти")}</button></div></header>
    {error&&<p className={styles.error}>{error}</p>}{notice&&<p className={styles.success}>{notice}</p>}
    {workspace.profile.status!=="APPROVED"&&<div className={styles.notice}>{uiText("Публичный профиль и продажи станут доступны после модерации. Рабочие инструменты и настройка уже доступны.")}</div>}
    {workspace.profile.moderationNote && <div className={styles.notice}><strong>{uiText("Комментарий модератора к профилю")}</strong><p style={{whiteSpace:"pre-wrap",overflowWrap:"anywhere"}}>{workspace.profile.moderationNote}</p></div>}
    {tab==="overview"&&<><CoachOnboarding workspace={workspace} openTab={setTab}/><div className={styles.metrics}><Metric label={uiText("Клиентов за счёт пакета")} value={counts.coachPaidClients}/><Metric label={uiText("Самостоятельно оплачивают")} value={counts.clientPaidClients}/><Metric label={uiText("Нужна внимательность")} value={counts.attention}/><Metric label={uiText("Открытых заданий")} value={counts.openAssignments}/></div><div className={styles.layout}><ClientsTable workspace={workspace} open={async(id)=>{setSelected(await coachApi.client(id));setTab("clients")}}/><section className={`${styles.panel} ${styles.stack}`}><h2>{uiText("Быстрые действия")}</h2><button className={styles.button} onClick={()=>setTab(workspace.subscription?"clients":"plans")}><Plus size={17}/> {workspace.subscription?uiText("Пригласить клиента"):uiText("Подключить пакет")}</button><button className={`${styles.button} ${styles.secondary}`} onClick={()=>setTab("scheduling")}><CalendarClock size={17}/> {uiText(" Настроить расписание")}</button><button className={`${styles.button} ${styles.secondary}`} onClick={()=>setTab("services")}><HandCoins size={17}/> {uiText(" Добавить услугу")}</button><Link className={`${styles.button} ${styles.secondary}`} href="/partners"><CircleDollarSign size={17}/> {uiText(" Комиссии и выплаты")}</Link></section></div></>}
    {tab==="clients"&&<ClientsView workspace={workspace} selected={selected} setSelected={setSelected} setError={setError} setNotice={setNotice} openPlans={()=>setTab("plans")}/>}
    {tab==="scheduling"&&<SchedulingView workspace={workspace} refresh={load} setError={setError} setNotice={setNotice}/>}
    {tab==="services"&&<ServicesView workspace={workspace} refresh={load} setError={setError} setNotice={setNotice}/>} 
    {tab==="plans"&&<PlansView workspace={workspace} refresh={load} setError={setError} setNotice={setNotice}/>}
    {tab==="site"&&<SiteView workspace={workspace} refresh={load} setError={setError} setNotice={setNotice}/>} 
    {tab==="telegram"&&<TelegramView workspace={workspace}/>}
    {tab==="rewards"&&<RewardsView workspace={workspace} refresh={load} setError={setError} setNotice={setNotice}/>} 
    {tab==="profile"&&<ProfileView workspace={workspace} refresh={load} setError={setError} setNotice={setNotice}/>} 
    </section><nav className={styles.mobileNav} aria-label={uiText("Разделы кабинета")}>{tabs().map(([id,label,Icon])=><button key={id} className={tab===id?styles.active:""} onClick={()=>{setTab(id);setSelected(null)}}><Icon size={19}/>{label}</button>)}</nav></div></main>
}

function CoachLogin({onDone}:{onDone:()=>void}){
  useUiLocale();
  const[mode,setMode]=useState<"login"|"register">("login");
  const[email,setEmail]=useState("");const[password,setPassword]=useState("");const[passwordRepeat,setPasswordRepeat]=useState("");
  const[name,setName]=useState("");const[practice,setPractice]=useState("");const[accepted,setAccepted]=useState(false);
  const[error,setError]=useState("");const[busy,setBusy]=useState(false);const[recoveryOpen,setRecoveryOpen]=useState(false);
  async function submit(e:React.FormEvent){e.preventDefault();if(mode==="register"&&password!==passwordRepeat){setError(uiText("Пароли не совпадают"));return}setBusy(true);setError("");try{if(mode==="register"){await partnerPortalApi.register({email,password,displayName:name.trim(),accountName:practice.trim()||name.trim(),accountType:"individual",idempotencyKey:makeKey()})}else{await partnerPortalApi.login({email,password})}onDone()}catch(reason){setError(reason instanceof Error?reason.message:uiText("Не удалось продолжить"))}finally{setBusy(false)}}
  const recoveryHref=`mailto:orken.eco@gmail.com?subject=${encodeURIComponent(uiText("Восстановление доступа к кабинету коуча ORKEN"))}&body=${encodeURIComponent(uiText("Email аккаунта: {v0}\n\nПрошу восстановить доступ к кабинету коуча.", { v0: email.trim()||uiText("укажите email") }))}`;
  return <main className={styles.page}><section className={styles.auth} aria-labelledby="coach-auth-title"><Link className={styles.brand} href="/">ORKEN.LIFE</Link><span className={styles.badge}>{uiText("Кабинет коуча")}</span><h1 id="coach-auth-title">{mode==="login"?uiText("Вход для коуча"):uiText("Создайте кабинет коуча")}</h1><p>{mode==="login"?uiText("Войдите, чтобы управлять клиентами, расписанием и пакетом мест."):uiText("Одна регистрация открывает кабинет коуча и партнёрскую программу ORKEN.")}</p><div className={styles.authTabs} role="tablist" aria-label={uiText("Вход или регистрация")}><button type="button" className={mode==="login"?styles.authTabActive:""} onClick={()=>{setMode("login");setRecoveryOpen(false);setError("")}}>{uiText("Войти")}</button><button type="button" className={mode==="register"?styles.authTabActive:""} onClick={()=>{setMode("register");setRecoveryOpen(false);setError("")}}>{uiText("Зарегистрироваться")}</button></div><form onSubmit={submit}>{mode==="register"&&<><label>{uiText("Имя и фамилия")}<input value={name} onChange={e=>setName(e.target.value)} autoComplete="name" minLength={2} required/></label><label>{uiText("Название практики ")}<span className={styles.optional}>{uiText("необязательно")}</span><input value={practice} onChange={e=>setPractice(e.target.value)} autoComplete="organization" placeholder={uiText("Например, Анна Орлова")}/></label></>}<label>Email<input type="email" value={email} onChange={e=>setEmail(e.target.value)} autoComplete="email" required/></label><label>{uiText("Пароль")}<input type="password" value={password} onChange={e=>setPassword(e.target.value)} minLength={mode==="register"?12:undefined} autoComplete={mode==="register"?"new-password":"current-password"} required/>{mode==="register"&&<span className={styles.fieldHelp}>{uiText("Не менее 12 символов")}</span>}</label>{mode==="login"&&<button className={styles.textButton} type="button" aria-expanded={recoveryOpen} onClick={()=>setRecoveryOpen(value=>!value)}><KeyRound size={15}/> {uiText(" Забыли пароль?")}</button>}{mode==="login"&&recoveryOpen&&<div className={styles.recoveryPanel}><div><h2>{uiText("Восстановление доступа")}</h2><p>{uiText("Пароль хранится в Partner Core. Отправьте запрос в поддержку с email аккаунта. Старый пароль указывать не нужно.")}</p></div><a className={`${styles.button} ${styles.secondary}`} href={recoveryHref}><Mail size={16}/> {uiText(" Написать в поддержку")}</a></div>}{mode==="register"&&<><label>{uiText("Повторите пароль")}<input type="password" value={passwordRepeat} onChange={e=>setPasswordRepeat(e.target.value)} minLength={12} autoComplete="new-password" required/></label><label className={styles.consent}><input type="checkbox" checked={accepted} onChange={e=>setAccepted(e.target.checked)} required/><span>{uiText("Принимаю ")}<Link href="/offer">{uiText("Оферту")}</Link> {uiText(" и ")}<Link href="/privacy">{uiText("Политику конфиденциальности")}</Link></span></label></>}{error&&<p className={styles.error} role="alert">{error}</p>}<button className={styles.button} disabled={busy||(mode==="register"&&!accepted)}>{mode==="register"?<UserPlus size={17}/>:<LogIn size={17}/>} {busy?uiText("Проверяем..."):mode==="register"?uiText("Создать кабинет"):uiText("Войти")}</button></form><p className={styles.authFoot}>{uiText("Учётная запись хранится в Partner Core. ORKEN не хранит пароль коуча.")}</p></section></main>
}

function CoachOnboarding({workspace,openTab}:{workspace:CoachWorkspaceResponse;openTab:(tab:Tab)=>void}){
  useUiLocale();
  const profileReady=Boolean(workspace.profile.headline&&workspace.profile.bio&&workspace.profile.specializations.length);
  const packageReady=Boolean(workspace.subscription);
  const scheduleReady=workspace.scheduling.provider==="ORKEN"&&workspace.scheduling.active&&workspace.scheduling.availabilityRules.some(rule=>rule.active);
  const clientReady=workspace.clients.length>0;
  const steps=[
    {label:uiText("Заполните профиль"),detail:uiText("Добавьте специализацию и информацию о себе."),done:profileReady,tab:"profile" as Tab},
    {label:uiText("Подключите пакет"),detail:packageReady?uiText("{v0}: доступно мест {v1}.", { v0: workspace.subscription?.plan.name, v1: workspace.subscription?.availableSlots??uiText("без лимита") }):uiText("Стартовый пакет рассчитан на 5 клиентов."),done:packageReady,tab:"plans" as Tab},
    {label:uiText("Настройте расписание"),detail:uiText("Укажите рабочие дни и часы внутри ORKEN."),done:scheduleReady,tab:"scheduling" as Tab},
    {label:uiText("Пригласите клиента"),detail:uiText("Отправьте клиенту персональную ссылку подключения."),done:clientReady,tab:"clients" as Tab}
  ];
  const next=steps.find(step=>!step.done);
  return <section className={styles.onboarding}><div className={styles.onboardingHead}><div><span className={styles.badge}>{uiText("Начало работы")}</span><h2>{next?uiText("Подготовьте кабинет к работе"):uiText("Кабинет готов к работе")}</h2><p>{next?uiText("Пройдите четыре шага. Настройки сохраняются, к ним можно вернуться в любое время."):uiText("Можно приглашать клиентов, назначать шаги и давать обратную связь.")}</p></div>{next&&<button className={styles.button} onClick={()=>openTab(next.tab)}>{uiText("Продолжить")}</button>}</div><ol>{steps.map((step,index)=><li key={step.label} className={step.done?styles.onboardingDone:""}><span>{step.done?<CheckCircle2 size={19}/>:index+1}</span><button type="button" onClick={()=>openTab(step.tab)}><strong>{step.label}</strong><small>{step.detail}</small></button></li>)}</ol></section>
}
function Metric({label,value}:{label:string;value:number|string}){
  useUiLocale();return <div className={styles.metric}><span>{label}</span><strong>{value}</strong></div>}
function ClientsTable({workspace,open}:{workspace:CoachWorkspaceResponse;open:(id:string)=>void}){
  useUiLocale();
  return <section className={styles.panel}>
    <h2>{uiText("Клиенты")}</h2>
    <p>{uiText("Здесь собраны подопечные, их последние отметки состояния и сигналы внимания.")}</p>
    {workspace.clients.length>0?<div className={styles.tableWrap}><table className={styles.table}><thead><tr><th>{uiText("Клиент")}</th><th>{uiText("Среднее")}</th><th>{uiText("Последняя отметка")}</th><th></th></tr></thead><tbody>{workspace.clients.slice(0,8).map(client=><tr key={client.relationshipId}><td><div className={styles.client}><span className={styles.avatar}>{client.avatarUrl?<img src={client.avatarUrl} alt=""/>:<UserRound size={17}/>}</span><div>{client.name||client.email}<br/><small className={client.attentionReason?styles.flag:styles.good}>{client.attentionReason||uiText("Ритм стабилен")}</small></div></div></td><td>{client.weeklyAverage??"—"}</td><td>{client.lastCheckinAt?date(client.lastCheckinAt):uiText("Нет отметок")}</td><td><button className={styles.rowButton} onClick={()=>open(client.relationshipId)}>{uiText("Открыть")}</button></td></tr>)}</tbody></table></div>:<div className={styles.emptyGuide}>
      <UsersRound size={30}/><h3>{uiText("Здесь появятся ваши клиенты")}</h3>
      <p>{uiText("Это список подопечных, а не экран ежедневной отметки. Создайте приглашение справа. После подключения клиента вы сможете открыть его состояние, инсайты, обратную связь и задания.")}</p>
      <div className={styles.guideSteps}><span><strong>1</strong> {uiText(" Создайте ссылку")}</span><span><strong>2</strong> {uiText(" Клиент примет приглашение")}</span><span><strong>3</strong> {uiText(" Данные появятся с его согласия")}</span></div>
    </div>}
  </section>
}
function ClientsView({workspace,selected,setSelected,setError,setNotice,openPlans}:{workspace:CoachWorkspaceResponse;selected:CoachClientDetail|null;setSelected:(v:CoachClientDetail|null)=>void;setError:(v:string)=>void;setNotice:(v:string)=>void;openPlans:()=>void}){
  useUiLocale();
  const[email,setEmail]=useState("");
  const packageSlots=workspace.subscription?.availableSlots;
  const canUsePackage=Boolean(workspace.subscription&&(packageSlots===null||packageSlots===undefined||packageSlots>0));
  const[funding,setFunding]=useState<"COACH_PAID"|"CLIENT_PAID">(canUsePackage?"COACH_PAID":"CLIENT_PAID");
  const[link,setLink]=useState("");
  const[msg,setMsg]=useState("");
  const[taskTitle,setTaskTitle]=useState("");
  const[task,setTask]=useState("");
  const[habitTitle,setHabitTitle]=useState("");
  const[habitPractice,setHabitPractice]=useState("");
  const[section,setSection]=useState<ClientSection>("state");

  useEffect(()=>setSection("state"),[selected?.client.relationshipId]);

  async function invite(){try{const result=await coachApi.invite({email:email||undefined,funding});setLink(result.connectUrl);setNotice(uiText("Приглашение создано. Отправьте ссылку клиенту — она действует 14 дней."))}catch(e){setError(e instanceof Error?e.message:uiText("Не удалось создать приглашение"))}}
  async function open(id:string){try{setSelected(await coachApi.client(id))}catch(e){setError(e instanceof Error?e.message:uiText("Ошибка"))}}
  async function sendFeedback(){if(!selected||!msg.trim())return;try{await coachApi.message(selected.client.relationshipId,msg.trim());setMsg("");setNotice(uiText("Обратная связь отправлена и уже видна клиенту в разделе «Мой коуч»."));await open(selected.client.relationshipId)}catch(e){setError(e instanceof Error?e.message:uiText("Не удалось отправить обратную связь"))}}
  async function addAssignment(){if(!selected||!taskTitle.trim()||!task.trim())return;try{await coachApi.assignment(selected.client.relationshipId,{title:taskTitle.trim(),details:task.trim()});setTaskTitle("");setTask("");setNotice(uiText("Задание назначено"));await open(selected.client.relationshipId)}catch(e){setError(e instanceof Error?e.message:uiText("Не удалось назначить задание"))}}
  async function addHabit(){if(!selected||!habitTitle.trim()||!habitPractice.trim())return;try{await coachApi.habit(selected.client.relationshipId,{title:habitTitle.trim(),focus:habitTitle.trim(),practice:habitPractice.trim(),why:uiText("Поддерживает текущую цель работы с коучем")});setHabitTitle("");setHabitPractice("");setNotice(uiText("Привычка отправлена клиенту"));await open(selected.client.relationshipId)}catch(e){setError(e instanceof Error?e.message:uiText("Не удалось отправить привычку"))}}

  if(!selected)return <div className={styles.layout}><ClientsTable workspace={workspace} open={open}/><section className={`${styles.panel} ${styles.form}`}><h2>{uiText("Пригласить клиента")}</h2><p>{uiText("Клиент сам подтверждает доступ к состоянию и отдельно — к дневнику.")}</p>{!canUsePackage&&<div className={styles.packageHint}><Package size={19}/><div><strong>{workspace.subscription?uiText("В пакете нет свободных мест"):uiText("Пакет клиентов не подключён")}</strong><span>{uiText("Приглашение всё равно можно создать: выберите оплату клиентом или подключите пакет.")}</span></div><button className={`${styles.button} ${styles.secondary}`} onClick={openPlans}>{uiText("Выбрать пакет")}</button></div>}<label>{uiText("Email (необязательно)")}<input className={styles.control} value={email} onChange={e=>setEmail(e.target.value)} /></label><label>{uiText("Кто оплачивает доступ")}<select className={styles.select} value={funding} onChange={e=>setFunding(e.target.value as "COACH_PAID"|"CLIENT_PAID")}><option value="COACH_PAID" disabled={!canUsePackage}>{uiText("Коуч, из пакета мест")}{!canUsePackage?uiText(" — недоступно"):""}</option><option value="CLIENT_PAID">{uiText("Клиент самостоятельно")}</option></select></label><small className={styles.fieldHelp}>{funding==="COACH_PAID"?uiText("После принятия приглашения клиент займёт одно место в вашем пакете."):uiText("Место в пакете не расходуется. Клиент сможет оплатить обычный тариф ORKEN самостоятельно.")}</small><button className={styles.button} onClick={invite}><Plus size={17}/> {uiText(" Создать приглашение")}</button>{link&&<div className={styles.stack}><label>{uiText("Ссылка для клиента")}<input className={styles.control} readOnly value={link}/></label><button className={`${styles.button} ${styles.secondary}`} onClick={()=>navigator.clipboard.writeText(link)}><Link2 size={16}/> {uiText(" Скопировать ссылку")}</button></div>}</section></div>;

  const clientName=selected.client.name||selected.client.email;
  const sections:Array<[ClientSection,string,typeof Activity,number?]>=[
    ["state",uiText("Состояние"),Activity],
    ["insights",uiText("Инсайты"),BookOpenText,selected.insights.length],
    ["feedback",uiText("Обратная связь"),MessageSquare,selected.messages.filter(item=>item.authorRole==="CLIENT").length],
    ["assignments",uiText("Задания и привычки"),ClipboardList,selected.assignments.filter(item=>item.status==="OPEN").length]
  ];

  return <div className={styles.stack}>
    <button className={styles.backButton} onClick={()=>setSelected(null)}><ChevronLeft size={17}/> {uiText(" Все клиенты")}</button>
    <section className={styles.clientHeader}><span className={styles.avatar}>{selected.client.avatarUrl?<img src={selected.client.avatarUrl} alt=""/>:<UserRound size={19}/>}</span><div><h2>{clientName}</h2><p>{selected.client.email} · {selected.client.status==="ACTIVE"?uiText("Активная программа"):uiText("Доступ не активен")}</p></div><div className={styles.consentBadges}><span className={selected.client.metricsConsent?styles.goodBadge:styles.mutedBadge}>{uiText("Состояние: ")}{selected.client.metricsConsent?uiText("доступно"):uiText("закрыто")}</span><span className={selected.client.journalConsent?styles.goodBadge:styles.mutedBadge}>{uiText("Дневник: ")}{selected.client.journalConsent?uiText("доступен"):uiText("закрыт")}</span></div></section>
    <nav className={styles.clientNav} aria-label={uiText("Разделы карточки клиента")}>{sections.map(([id,label,Icon,count])=><button key={id} className={section===id?styles.activeSection:""} onClick={()=>setSection(id)}><Icon size={17}/><span>{label}</span>{count!==undefined&&count>0&&<b>{count}</b>}</button>)}</nav>

    {section==="state"&&<div className={styles.stack}>
      <div className={styles.metrics}><Metric label={uiText("Энергия")} value={selected.client.latestEnergy??"—"}/><Metric label={uiText("Ясность")} value={selected.client.latestClarity??"—"}/><Metric label={uiText("Устойчивость")} value={selected.client.latestStability??"—"}/><Metric label={uiText("Среднее недели")} value={selected.client.weeklyAverage??"—"}/></div>
      <section className={styles.panel}><div className={styles.sectionHead}><div><h2>{uiText("Прогресс внутреннего состояния")}</h2><p>{uiText("Ежедневные отметки клиента по шкале от 1 до 10.")}</p></div><span className={styles.badge}>{selected.metrics.length} {uiText(" отметок")}</span></div>{!selected.client.metricsConsent?<div className={styles.notice}>{uiText("Клиент не дал или отозвал доступ к показателям состояния.")}</div>:selected.metrics.length?<StateChart points={selected.metrics}/>:<div className={styles.empty}>{uiText("Клиент ещё не сделал ни одной отметки состояния.")}</div>}</section>
      {selected.correlations.length>0&&<section className={`${styles.panel} ${styles.stack}`}><h2>{uiText("Наблюдаемые связи")}</h2><p>{uiText("Связи рассчитаны по отметкам клиента и не означают причинность.")}</p>{selected.correlations.map((item,index)=><div className={styles.insightCard} key={`${item.habitTitle}-${item.metric}-${index}`}>{uiText(item.message)}</div>)}</section>}
    </div>}

    {section==="insights"&&<section className={`${styles.panel} ${styles.stack}`}><div className={styles.sectionHead}><div><h2>{uiText("Инсайты и записи клиента")}</h2><p>{uiText("Записи Навигатора, которыми клиент разрешил делиться с вами.")}</p></div><BookOpenText size={22}/></div>{!selected.client.journalConsent?<div className={styles.notice}>{uiText("Дневник закрыт. Клиент может отдельно разрешить доступ в разделе «Мой коуч».")}</div>:selected.insights.length?selected.insights.map(item=><article className={styles.insightCard} key={item.id}><p>{item.text}</p><small>{date(item.createdAt)}</small></article>):<div className={styles.empty}>{uiText("У клиента пока нет записей и инсайтов.")}</div>}</section>}

    {section==="feedback"&&<div className={styles.feedbackLayout}><section className={`${styles.panel} ${styles.stack}`}><div className={styles.sectionHead}><div><h2>{uiText("История обратной связи")}</h2><p>{uiText("Ваш текст сразу появляется у клиента в разделе «Мой коуч».")}</p></div><MessageSquare size={22}/></div>{selected.messages.length?selected.messages.map(item=><article className={`${styles.feedbackItem} ${item.authorRole==="CLIENT"?styles.fromClient:""}`} key={item.id}><div className={styles.messageMeta}><strong>{item.authorRole==="CLIENT"?uiText("Ответ клиента"):uiText("От вас")}</strong><small>{date(item.createdAt)}</small></div><p>{item.text}</p></article>):<div className={styles.empty}>{uiText("Обратной связи пока нет. Напишите первое сообщение справа.")}</div>}</section><section className={`${styles.panel} ${styles.form}`}><h2>{uiText("Новая обратная связь")}</h2><p>{uiText("Сформулируйте наблюдение, рекомендацию или следующий шаг для клиента.")}</p><label>{uiText("Текст")}<textarea className={styles.textarea} value={msg} onChange={e=>setMsg(e.target.value)} placeholder={uiText("Например: на этой неделе ясность стала устойчивее. Сохрани текущий ритм и обрати внимание...")}/></label><button className={styles.button} disabled={selected.client.status!=="ACTIVE"||!msg.trim()} onClick={sendFeedback}><Send size={16}/> {uiText(" Отправить клиенту")}</button>{selected.client.status!=="ACTIVE"&&<div className={styles.notice}>{uiText("Отправка станет доступна после активации программы.")}</div>}</section></div>}

    {section==="assignments"&&<div className={styles.assignmentGrid}><section className={`${styles.panel} ${styles.stack}`}><h2>{uiText("Текущие задания")}</h2>{selected.assignments.length?selected.assignments.map(item=><article className={styles.itemCard} key={item.id}><div className={styles.itemTop}><div><span className={styles.badge}>{item.status==="OPEN"?uiText("Открыто"):uiText("Выполнено")}</span><h3>{item.title}</h3></div>{item.status==="COMPLETED"&&<Check size={18}/>}</div><p>{item.details}</p></article>):<div className={styles.empty}>{uiText("Заданий пока нет.")}</div>}<h2>{uiText("Привычки от вас")}</h2>{selected.habitAssignments.length?selected.habitAssignments.map(item=><article className={styles.itemCard} key={item.id}><span className={styles.badge}>{item.status}</span><h3>{item.title}</h3><p>{item.practice}</p></article>):<div className={styles.empty}>{uiText("Авторских привычек пока нет.")}</div>}</section><section className={`${styles.panel} ${styles.stack}`}><div className={styles.formBlock}><h2>{uiText("Новое задание")}</h2><input className={styles.control} value={taskTitle} onChange={e=>setTaskTitle(e.target.value)} placeholder={uiText("Название задания")}/><textarea className={styles.textarea} value={task} onChange={e=>setTask(e.target.value)} placeholder={uiText("Что нужно сделать")}/><button className={`${styles.button} ${styles.secondary}`} disabled={selected.client.status!=="ACTIVE"||!taskTitle.trim()||!task.trim()} onClick={addAssignment}><ClipboardList size={16}/> {uiText(" Назначить")}</button></div><div className={styles.formBlock}><h2>{uiText("Авторская привычка")}</h2><input className={styles.control} value={habitTitle} onChange={e=>setHabitTitle(e.target.value)} placeholder={uiText("Название привычки")}/><textarea className={styles.textarea} value={habitPractice} onChange={e=>setHabitPractice(e.target.value)} placeholder={uiText("Практика и мягкий шаг")}/><button className={`${styles.button} ${styles.secondary}`} disabled={selected.client.status!=="ACTIVE"||!habitTitle.trim()||!habitPractice.trim()} onClick={addHabit}><Plus size={16}/> {uiText(" Отправить привычку")}</button></div></section></div>}
  </div>
}
function StateChart({points}:{points:Array<{date:string;energy:number;clarity:number;stability:number}>}){
  useUiLocale();
  return <div className={styles.chart}><ResponsiveContainer width="100%" height="100%"><LineChart data={points.slice(-31)} margin={{top:8,right:8,left:-18,bottom:0}}><CartesianGrid stroke="#1b2c40" vertical={false}/><XAxis dataKey="date" stroke="#7890aa" tick={{fontSize:11}} tickFormatter={(value)=>String(value).slice(5)}/><YAxis domain={[1,10]} stroke="#7890aa" tick={{fontSize:11}}/><Tooltip contentStyle={{background:"#08131f",border:"1px solid #29415b",borderRadius:6}} labelFormatter={(value)=>uiText("Дата: {v0}", { v0: value })}/><Legend/><Line type="monotone" dataKey="energy" name={uiText("Энергия")} stroke="#13d4ec" strokeWidth={2} dot={false}/><Line type="monotone" dataKey="clarity" name={uiText("Ясность")} stroke="#a965ea" strokeWidth={2} dot={false}/><Line type="monotone" dataKey="stability" name={uiText("Устойчивость")} stroke="#24d3a2" strokeWidth={2} dot={false}/></LineChart></ResponsiveContainer></div>
}
function SchedulingView({workspace,refresh,setError,setNotice}:{workspace:CoachWorkspaceResponse;refresh:()=>void;setError:(v:string)=>void;setNotice:(v:string)=>void}){
  useUiLocale();
  const schedule=workspace.scheduling;
  const[timezone,setTimezone]=useState(schedule.timezone);
  const[duration,setDuration]=useState(schedule.slotDurationMinutes);
  const[bufferAfter,setBufferAfter]=useState(schedule.bufferAfterMinutes);
  const[minNotice,setMinNotice]=useState(schedule.minNoticeMinutes);
  const[horizon,setHorizon]=useState(schedule.bookingHorizonDays);
  const[active,setActive]=useState(schedule.active);
  const[rules,setRules]=useState(()=>Array.from({length:7},(_,index)=>{const found=schedule.availabilityRules.find(rule=>rule.weekday===index+1);return{weekday:index+1,active:Boolean(found?.active),startMinute:found?.startMinute??540,endMinute:found?.endMinute??1080}}));
  const[exceptionDate,setExceptionDate]=useState("");
  const[busy,setBusy]=useState(false);
  async function save(){setBusy(true);setError("");try{await coachApi.updateScheduling({provider:"ORKEN",timezone,slotDurationMinutes:duration,bufferBeforeMinutes:0,bufferAfterMinutes:bufferAfter,minNoticeMinutes:minNotice,bookingHorizonDays:horizon,active});await coachApi.updateAvailability(rules);setNotice(uiText("Расписание ORKEN сохранено"));refresh()}catch(error){setError(error instanceof Error?error.message:uiText("Не удалось сохранить расписание"))}finally{setBusy(false)}}
  return <div className={styles.stack}>
    <section className={styles.scheduleIntro}><CalendarClock size={25}/><div><h2>{uiText("Встроенное расписание ORKEN")}</h2><p>{uiText("Задайте рабочие часы и исключения. Клиент выберет свободное время внутри ORKEN, без подключения внешнего календаря.")}</p>{schedule.provider!=="ORKEN"&&<span>{uiText("После сохранения текущий внешний календарь будет заменён расписанием ORKEN.")}</span>}</div><Check size={20}/></section>
    <div className={styles.layout}><section className={`${styles.panel} ${styles.form}`}><h2>{uiText("Рабочие часы")}</h2>{rules.map((rule,index)=><div className={styles.scheduleRow} key={rule.weekday}><label><input type="checkbox" checked={rule.active} onChange={event=>setRules(current=>current.map((item,i)=>i===index?{...item,active:event.target.checked}:item))}/>{weekdayLabel(rule.weekday)}</label><input className={styles.control} type="time" disabled={!rule.active} value={minuteToTime(rule.startMinute)} onChange={event=>setRules(current=>current.map((item,i)=>i===index?{...item,startMinute:timeToMinute(event.target.value)}:item))}/><span>—</span><input className={styles.control} type="time" disabled={!rule.active} value={minuteToTime(rule.endMinute)} onChange={event=>setRules(current=>current.map((item,i)=>i===index?{...item,endMinute:timeToMinute(event.target.value)}:item))}/></div>)}</section>
      <section className={`${styles.panel} ${styles.form}`}><h2>{uiText("Правила записи")}</h2><label>{uiText("Часовой пояс")}<input className={styles.control} value={timezone} onChange={event=>setTimezone(event.target.value)} placeholder="Europe/Moscow"/></label><div className={styles.formGrid}><label>{uiText("Длительность")}<select className={styles.select} value={duration} onChange={event=>setDuration(Number(event.target.value))}><option value={30}>{uiText("30 минут")}</option><option value={45}>{uiText("45 минут")}</option><option value={60}>{uiText("60 минут")}</option><option value={90}>{uiText("90 минут")}</option></select></label><label>{uiText("Перерыв после")}<input className={styles.control} type="number" min="0" max="120" value={bufferAfter} onChange={event=>setBufferAfter(Number(event.target.value))}/></label><label>{uiText("Не позднее, часов")}<input className={styles.control} type="number" min="0" value={Math.round(minNotice/60)} onChange={event=>setMinNotice(Number(event.target.value)*60)}/></label><label>{uiText("Запись вперёд, дней")}<input className={styles.control} type="number" min="1" max="180" value={horizon} onChange={event=>setHorizon(Number(event.target.value))}/></label></div><label><input type="checkbox" checked={active} onChange={event=>setActive(event.target.checked)}/> {uiText(" Принимать новые записи")}</label><button className={styles.button} disabled={busy} onClick={save}><Save size={17}/>{busy?uiText("Сохраняем..."):uiText("Сохранить расписание")}</button></section></div>
    <div className={styles.layout}><section className={`${styles.panel} ${styles.form}`}><h2>{uiText("Выходные и исключения")}</h2><div className={styles.actions}><input className={styles.control} type="date" value={exceptionDate} onChange={event=>setExceptionDate(event.target.value)}/><button className={`${styles.button} ${styles.secondary}`} disabled={!exceptionDate} onClick={async()=>{try{await coachApi.addScheduleException({date:exceptionDate,isAvailable:false,note:uiText("Выходной")});setExceptionDate("");setNotice(uiText("Выходной добавлен"));refresh()}catch(error){setError(error instanceof Error?error.message:uiText("Ошибка"))}}}>{uiText("Добавить выходной")}</button></div>{schedule.availabilityExceptions.map(item=><div className={styles.exceptionRow} key={item.id}><span>{new Intl.DateTimeFormat(getFormatLocale(),{dateStyle:"medium"}).format(new Date(`${item.date}T00:00:00`))}</span><small>{item.note||(!item.isAvailable?uiText("Выходной"):uiText("Дополнительное время"))}</small><button className={styles.rowButton} title={uiText("Удалить")} onClick={async()=>{await coachApi.deleteScheduleException(item.id);refresh()}}><Trash2 size={16}/></button></div>)}</section>
      <section className={styles.panel}><h2>{uiText("Ближайшие встречи")}</h2><div className={styles.stack}>{workspace.appointments.filter(item=>item.status!=="CANCELLED").slice(0,12).map(item=><article className={styles.appointment} key={item.id}><div><span className={styles.badge}>{item.status}</span><h3>{item.serviceTitle||uiText("Консультация")}</h3><p>{new Intl.DateTimeFormat(getFormatLocale(),{dateStyle:"medium",timeStyle:"short",timeZone:item.timezone}).format(new Date(item.startsAt))}{item.client?` · ${item.client.name||item.client.email}`:""}</p></div><div className={styles.actions}>{item.meetingUrl&&<a className={styles.rowButton} href={item.meetingUrl} target="_blank" rel="noreferrer">{uiText("Встреча")}</a>}{item.status==="CONFIRMED"&&<button className={styles.rowButton} onClick={async()=>{await coachApi.updateAppointment(item.id,"COMPLETED");refresh()}}>{uiText("Завершить")}</button>}</div></article>)}{workspace.appointments.length===0&&<div className={styles.empty}>{uiText("Записей пока нет.")}</div>}</div></section></div>
  </div>
}

function ServicesView({workspace,refresh,setError,setNotice}:{workspace:CoachWorkspaceResponse;refresh:()=>void;setError:(v:string)=>void;setNotice:(v:string)=>void}){
  useUiLocale();
  const offers=workspace.serviceOffers;
  const paidServicesEnabled=workspace.commerce?.servicesEnabled??false;
  const[type,setType]=useState<"ONGOING_SUPPORT"|"CONSULTATION">("ONGOING_SUPPORT");
  const[model,setModel]=useState<"INCLUDED"|"CLIENT_PAID">(paidServicesEnabled?"CLIENT_PAID":"INCLUDED");
  const[title,setTitle]=useState("");const[description,setDescription]=useState("");const[amount,setAmount]=useState("0");
  const[editing,setEditing]=useState<CoachServiceOfferSummary|null>(null);
  const[busy,setBusy]=useState(false);
  const form=useRef<HTMLElement>(null);
  function edit(offer:CoachServiceOfferSummary){setEditing(offer);setType(offer.type);setModel(offer.paymentModel);setTitle(offer.title);setDescription(offer.description);setAmount(String(offer.amount/100));form.current?.scrollIntoView({behavior:"smooth",block:"start"})}
  function reset(){setEditing(null);setTitle("");setDescription("");setAmount("0");setModel(paidServicesEnabled?"CLIENT_PAID":"INCLUDED")}
  async function save(){setBusy(true);setError("");try{await coachApi.saveOffer({...(editing?{id:editing.id}:{}),type,paymentModel:model,title,description,amount:model==="CLIENT_PAID"?Math.round(Number(amount)*100):0,currency:editing?.currency||"usd",calendlyEventTypeUri:editing?.calendlyEventTypeUri||null,calendlySchedulingUrl:editing?.calendlySchedulingUrl||null});setNotice(uiText("Услуга сохранена. Отправьте её на модерацию."));reset();refresh()}catch(e){setError(e instanceof Error?e.message:uiText("Ошибка"))}finally{setBusy(false)}}
  async function submit(id:string){setBusy(true);setError("");try{await coachApi.submitOffer(id);setNotice(uiText("Услуга отправлена на модерацию"));refresh()}catch(e){setError(e instanceof Error?e.message:uiText("Ошибка"))}finally{setBusy(false)}}
  return <div className={styles.layout}>
    <section className={styles.panel}><h2>{uiText("Ваши услуги")}</h2><p>{uiText("Опишите форматы работы, которые увидит клиент в каталоге после модерации.")}</p><div className={styles.stack}>
      {offers.map(o=><article className={styles.card} key={o.id}><span className={styles.badge}>{serviceStatusLabel(o)}</span><h3>{o.title}</h3><p>{o.description}</p><strong>{o.paymentModel==="INCLUDED"?uiText("Включено в программу"):money(o.amount,o.currency)}</strong>
        {o.moderationNote&&<div className={styles.notice}><strong>{uiText("Комментарий модератора")}</strong><p style={{whiteSpace:"pre-wrap",overflowWrap:"anywhere"}}>{o.moderationNote}</p></div>}
        {o.paymentModel==="CLIENT_PAID"&&o.coachShareBps==null&&<p className={styles.flag}>{uiText("Доли оплаты ещё не настроены администратором")}</p>}
        <div className={styles.topActions}><button className={`${styles.button} ${styles.secondary}`} disabled={busy} onClick={()=>edit(o)}><Pencil size={16}/>{uiText("Редактировать")}</button><button className={`${styles.button} ${styles.secondary}`} disabled={busy||!["DRAFT","REJECTED"].includes(o.status)} onClick={()=>submit(o.id)}><Send size={16}/>{uiText("Отправить на модерацию")}</button></div>
      </article>)}{offers.length===0&&<div className={styles.empty}>{uiText("Услуги пока не добавлены.")}</div>}
    </div></section>
    <section ref={form} className={`${styles.panel} ${styles.form}`}><h2>{editing?uiText("Редактирование услуги"):uiText("Новая услуга")}</h2>
      {!paidServicesEnabled&&<div className={styles.notice}>{uiText("Сейчас можно добавить услугу, включённую в вашу программу. Продажа отдельных консультаций через ORKEN появится после настройки выплат.")}</div>}
      <label>{uiText("Формат")}<select className={styles.select} value={type} onChange={e=>setType(e.target.value as "ONGOING_SUPPORT"|"CONSULTATION")}><option value="ONGOING_SUPPORT">{uiText("Ежемесячное ведение")}</option><option value="CONSULTATION">{uiText("Разовая консультация")}</option></select></label>
      <label>{uiText("Оплата")}<select className={styles.select} value={model} onChange={e=>setModel(e.target.value as "INCLUDED"|"CLIENT_PAID")}><option value="INCLUDED">{uiText("Включено в программу коуча")}</option>{(paidServicesEnabled||editing?.paymentModel==="CLIENT_PAID")&&<option value="CLIENT_PAID">{uiText("Клиент платит через ORKEN")}</option>}</select></label>
      <label>{uiText("Название")}<input className={styles.control} aria-label={uiText("Название")} value={title} maxLength={160} onChange={e=>setTitle(e.target.value)}/></label><label>{uiText("Что получает клиент")}<textarea className={styles.textarea} aria-label={uiText("Что получает клиент")} value={description} maxLength={3000} onChange={e=>setDescription(e.target.value)}/></label>
      {model==="CLIENT_PAID"&&<label>{uiText("Цена")} ({(editing?.currency||"usd").toUpperCase()})<input className={styles.control} type="number" min="0" step="0.01" value={amount} onChange={e=>setAmount(e.target.value)}/></label>}
      {type==="CONSULTATION"&&<p className={styles.fieldHelp}>{uiText("Клиент выберет свободное время во встроенном расписании ORKEN.")}</p>}
      <button className={styles.button} disabled={busy||title.trim().length<3||description.trim().length<10||(model==="CLIENT_PAID"&&(!Number.isFinite(Number(amount))||Number(amount)<=0))} onClick={save}><Save size={16}/>{uiText("Сохранить черновик")}</button>{editing&&<button className={`${styles.button} ${styles.secondary}`} disabled={busy} onClick={reset}>{uiText("Отмена")}</button>}
    </section>
  </div>
}
function serviceStatusLabel(offer:CoachServiceOfferSummary){return offer.status==="DRAFT"&&offer.moderationNote?uiText("На доработке"):({DRAFT:uiText("Черновик"),PENDING_REVIEW:uiText("На модерации"),APPROVED:uiText("Одобрено"),REJECTED:uiText("Отклонено"),PAUSED:uiText("Приостановлено")} as Record<string,string>)[offer.status]||offer.status}
function PlansView({workspace,refresh,setError,setNotice}:{workspace:CoachWorkspaceResponse;refresh:()=>void;setError:(v:string)=>void;setNotice:(v:string)=>void}){
  useUiLocale();
  const[busyPlan,setBusyPlan]=useState<string|null>(null);const[billingBusy,setBillingBusy]=useState(false);
  const packagesEnabled=workspace.commerce?.packagesEnabled??false;
  const currentPlanId=workspace.subscription?.plan.id;
  async function checkout(planId:string){setBusyPlan(planId);setError("");try{const result=await coachApi.checkoutPlan(planId,makeKey());if(!result.url)throw new Error(uiText("Платёжная страница не создана. Попробуйте ещё раз или обратитесь в поддержку."));window.location.assign(result.url)}catch(error){setError(error instanceof Error?error.message:uiText("Не удалось открыть оплату пакета"));setBusyPlan(null)}}
  async function openBilling(){setBillingBusy(true);setError("");try{const result=await coachApi.subscriptionPortal();window.location.assign(result.url)}catch(error){setError(error instanceof Error?error.message:uiText("Не удалось открыть управление оплатой"));setBillingBusy(false)}}
  async function changePlan(planId:string,planName:string){if(!window.confirm(uiText("Перейти на пакет «{v0}»? Новый лимит начнёт действовать сразу, новая цена — со следующего списания.", { v0: planName })))return;setBusyPlan(planId);setError("");try{const result=await coachApi.changePlan(planId,makeKey());const next=result.nextChargeAt?uiText(" Следующее списание: {v0}.", { v0: date(result.nextChargeAt) }):"";setNotice(uiText("Пакет изменён. Новый лимит уже доступен.{v0}", { v0: next }));refresh()}catch(error){setError(error instanceof Error?error.message:uiText("Не удалось изменить пакет"))}finally{setBusyPlan(null)}}
  return <div className={styles.stack}>
    {workspace.subscription?<section className={styles.panel}><div className={styles.sectionHead}><div><h2>{uiText("Текущий пакет: ")}{uiText(workspace.subscription.plan.name)}</h2><p>{workspace.subscription.coachPaidClients} {uiText(" из ")}{workspace.subscription.clientLimit} {uiText(" мест занято. Клиенты со своей подпиской: ")}{workspace.subscription.clientPaidClients}.</p><p className={styles.fieldHelp}>{workspace.subscription.cancelAtPeriodEnd?uiText("Подписка завершится {v0}.", { v0: workspace.subscription.currentPeriodEnd?date(workspace.subscription.currentPeriodEnd):uiText("в конце оплаченного периода") }):uiText("Следующее списание: {v0}.", { v0: workspace.subscription.currentPeriodEnd?date(workspace.subscription.currentPeriodEnd):uiText("дата уточняется") })}</p></div><span className={styles.goodBadge}>{workspace.subscription.status}</span></div><div className={styles.billingActions}><button className={`${styles.button} ${styles.secondary}`} type="button" onClick={openBilling} disabled={billingBusy}><CreditCard size={17}/>{billingBusy?uiText("Открываем Stripe..."):uiText("Карта, счета и отмена")}</button><span>{uiText("Платёжные данные открываются на защищённой странице Stripe.")}</span></div></section>:<section className={styles.planIntro}><Package size={24}/><div><h2>{uiText("Выберите пакет клиентов")}</h2><p>{uiText("Пакет нужен только для клиентов, доступ которым оплачиваете вы. Приглашать клиентов с самостоятельной оплатой можно без пакета.")}</p></div></section>}
    {!packagesEnabled&&<div className={styles.notice}>{uiText("Онлайн-оплата пакетов сейчас отключена администратором. Тарифы можно посмотреть, но подключить их до включения оплаты нельзя.")}</div>}
    <div className={styles.cards}>{workspace.plans.map(plan=>{
      const current=plan.id===currentPlanId;
      const busy=busyPlan===plan.id;
      return <article className={`${styles.card} ${current?styles.currentPlan:""}`} key={plan.id}><span className={styles.badge}>{plan.includedClients?uiText("{v0} мест", { v0: plan.includedClients }):uiText("Индивидуально")}</span><h3>{uiText(plan.name)}</h3><p>{plan.description ? uiText(plan.description) : ''}</p><strong>{plan.customQuote?uiText("По запросу"):uiText("{v0} / месяц", { v0: money(plan.amount,plan.currency) })}</strong>{plan.customQuote?<a className={`${styles.button} ${styles.secondary}`} href={uiText("mailto:orken.eco@gmail.com?subject=Пакет ORKEN более 30 клиентов")}>{uiText("Запросить условия")}</a>:current?<button className={styles.button} disabled>{uiText("Текущий пакет")}</button>:workspace.subscription?<button className={`${styles.button} ${styles.secondary}`} disabled={!packagesEnabled||Boolean(busyPlan)} onClick={()=>changePlan(plan.id,plan.name)}>{busy?uiText("Меняем пакет..."):uiText("Перейти на пакет")}</button>:<button className={styles.button} disabled={!packagesEnabled||Boolean(busyPlan)} onClick={()=>checkout(plan.id)}>{busy?uiText("Открываем оплату..."):uiText("Подключить пакет")}</button>}</article>
    })}</div>
  </div>
}
function SiteView({workspace,refresh,setError,setNotice}:{workspace:CoachWorkspaceResponse;refresh:()=>void;setError:(v:string)=>void;setNotice:(v:string)=>void}){
  useUiLocale();const[slug,setSlug]=useState(workspace.profile.slug);return <div className={styles.stack}>{workspace.sites.map(site=><SiteEditor key={site.id} site={site} refresh={refresh} setError={setError} setNotice={setNotice}/>)}<section className={styles.panel}><h2>{uiText("Подключить сайт")}</h2><label>{uiText("Адрес на ORKEN")}<input className={styles.control} value={slug} onChange={e=>setSlug(e.target.value.toLowerCase().replace(/[^a-z0-9-]/g,"-"))}/></label><div className={styles.cards}>{workspace.sitePlans.map(plan=><article className={styles.card} key={plan.id}><h3>{uiText(plan.name)}</h3><p>{plan.code==="premium"?uiText("Свой домен, редактируемые блоки, календарь и AI-чат."):uiText("Готовый шаблон на поддомене ORKEN.")}</p><strong>{money(plan.setupAmount,plan.currency)} + {money(plan.monthlySupportAmount,plan.currency)}{uiText("/мес")}</strong><button className={styles.button} onClick={async()=>{try{const r=await coachApi.checkoutSite(plan.id,slug);if(r.url)location.assign(r.url)}catch(e){setError(e instanceof Error?e.message:uiText("Ошибка"))}}}>{uiText("Подключить")}</button></article>)}</div></section></div>}
function SiteEditor({site,refresh,setError,setNotice}:{site:CoachWorkspaceResponse["sites"][number];refresh:()=>void;setError:(v:string)=>void;setNotice:(v:string)=>void}){
  useUiLocale();const content=site.content||{};const[heading,setHeading]=useState(String(content.title||""));const[subtitle,setSubtitle]=useState(String(content.subtitle||""));const[domain,setDomain]=useState(site.customDomain||"");const[verification,setVerification]=useState<{record:string;type:string;value:string}|null>(null);return <section className={`${styles.panel} ${styles.form}`}><div className={styles.siteHead}><div><h2>{uiText("Ваш сайт")}</h2><p><span className={styles.badge}>{site.status}</span> <a className={styles.link} href={`https://${site.customDomain||`${site.slug}.orken.life`}`} target="_blank">{site.customDomain||`${site.slug}.orken.life`} <ExternalLink size={14}/></a></p></div></div>{site.planCode==="premium"&&<><label>{uiText("Заголовок")}<input className={styles.control} value={heading} onChange={e=>setHeading(e.target.value)}/></label><label>{uiText("Короткое описание")}<textarea className={styles.textarea} value={subtitle} onChange={e=>setSubtitle(e.target.value)}/></label><label>{uiText("Собственный домен")}<input className={styles.control} value={domain} onChange={e=>setDomain(e.target.value)} placeholder="coach.example.com"/></label><div className={styles.actions}><button className={styles.button} onClick={async()=>{try{const result=await coachApi.updateSite(site.id,{content:{...content,title:heading,subtitle},customDomain:domain||null});setVerification(result.verification||null);setNotice(uiText("Настройки сайта сохранены"));refresh()}catch(e){setError(e instanceof Error?e.message:uiText("Ошибка"))}}}>{uiText("Сохранить")}</button>{site.customDomainStatus==="PENDING_VERIFICATION"&&<button className={`${styles.button} ${styles.secondary}`} onClick={async()=>{try{await coachApi.verifySiteDomain(site.id);setNotice(uiText("Домен подтверждён"));refresh()}catch(e){setError(e instanceof Error?e.message:uiText("TXT-запись пока не найдена"))}}}>{uiText("Проверить домен")}</button>}</div>{verification&&<div className={styles.notice}>{uiText("Добавьте DNS-запись: ")}<code>{verification.type} {verification.record} = {verification.value}</code></div>}</>}</section>}
function TelegramView({workspace}:{workspace:CoachWorkspaceResponse}){
  useUiLocale();return <section className={`${styles.panel} ${styles.telegramPanel}`}><MessageSquare size={28}/><div><h2>{uiText("Telegram-бот ORKEN")}</h2><p>{uiText("Отправьте ссылку клиенту, чтобы он мог перейти в ORKEN из Telegram. Бот использует ваш публичный профиль и сохраняет связь с клиентом.")}</p>{workspace.integrations.telegramBotUsername?<div className={styles.actions}><a className={styles.button} href={`https://t.me/${workspace.integrations.telegramBotUsername}?start=coach_${workspace.profile.slug}`} target="_blank" rel="noreferrer">{uiText("Открыть бота")}</a><button className={`${styles.button} ${styles.secondary}`} onClick={()=>navigator.clipboard.writeText(`https://t.me/${workspace.integrations.telegramBotUsername}?start=coach_${workspace.profile.slug}`)}>{uiText("Скопировать ссылку")}</button></div>:<span className={styles.flag}>{uiText("Telegram-бот временно недоступен")}</span>}</div></section>}
function RewardsView({workspace,refresh,setError,setNotice}:{workspace:CoachWorkspaceResponse;refresh:()=>void;setError:(v:string)=>void;setNotice:(v:string)=>void}){
  useUiLocale();const[title,setTitle]=useState("");const[description,setDescription]=useState("");const[points,setPoints]=useState("500");return <div className={styles.layout}><section className={styles.panel}><h2>{uiText("Награды за ORKEN Points")}</h2>{workspace.rewards.map(r=><article className={styles.card} key={r.id}><span className={styles.badge}>{r.status}</span><h3>{r.title}</h3><p>{r.description}</p><strong>{r.pointsCost} Points</strong></article>)}</section><section className={`${styles.panel} ${styles.form}`}><h2>{uiText("Новая награда")}</h2><p>{uiText("Награда появится у клиентов после модерации.")}</p><input className={styles.control} value={title} onChange={e=>setTitle(e.target.value)} placeholder={uiText("Название")}/><textarea className={styles.textarea} value={description} onChange={e=>setDescription(e.target.value)} placeholder={uiText("Что получает клиент")}/><input className={styles.control} type="number" value={points} onChange={e=>setPoints(e.target.value)}/><button className={styles.button} onClick={async()=>{try{await coachApi.createReward({title,description,pointsCost:Number(points),entitlementType:"manual"});setNotice(uiText("Награда отправлена на модерацию"));refresh()}catch(e){setError(e instanceof Error?e.message:uiText("Ошибка"))}}}>{uiText("Отправить")}</button></section></div>}
function ProfileView({workspace,refresh,setError,setNotice}:{workspace:CoachWorkspaceResponse;refresh:()=>void;setError:(v:string)=>void;setNotice:(v:string)=>void}){
  useUiLocale();const p=workspace.profile;const[name,setName]=useState(p.displayName);const[slug,setSlug]=useState(p.slug);const[headline,setHeadline]=useState(p.headline||"");const[bio,setBio]=useState(p.bio||"");const[city,setCity]=useState(p.city||"");const[spec,setSpec]=useState(p.specializations.join(", "));const[avatar,setAvatar]=useState(p.avatarUrl||"");const[accepting,setAccepting]=useState(p.acceptingOrders);return <section className={`${styles.panel} ${styles.form}`}><h2>{uiText("Публичный профиль")}</h2><div className={styles.photoUpload}>{avatar?<img src={avatar} alt={uiText("Фото профиля")}/>:<UserRound/>}<label className={styles.button}><ImageUp size={17}/> {uiText(" Загрузить фото")}<input type="file" accept="image/jpeg,image/png,image/webp" onChange={async e=>{const file=e.target.files?.[0];if(!file)return;try{const result=await coachApi.uploadAvatar(file);setAvatar(result.avatarUrl);setNotice(uiText("Фото загружено и отправлено на модерацию"));refresh()}catch(reason){setError(reason instanceof Error?reason.message:uiText("Не удалось загрузить фото"))}}}/></label></div><div className={styles.formGrid}><label>{uiText("Имя")}<input className={styles.control} value={name} onChange={e=>setName(e.target.value)}/></label><label>{uiText("Адрес профиля")}<input className={styles.control} value={slug} onChange={e=>setSlug(e.target.value)}/></label><label>{uiText("Город")}<input className={styles.control} value={city} onChange={e=>setCity(e.target.value)}/></label></div><label>{uiText("Короткое описание")}<input className={styles.control} value={headline} onChange={e=>setHeadline(e.target.value)}/></label><label>{uiText("О себе")}<textarea className={styles.textarea} value={bio} onChange={e=>setBio(e.target.value)}/></label><label>{uiText("Специализации через запятую")}<input className={styles.control} value={spec} onChange={e=>setSpec(e.target.value)}/></label><label><input type="checkbox" checked={accepting} onChange={e=>setAccepting(e.target.checked)}/> {uiText(" Принимаю новые заказы")}</label><button className={styles.button} onClick={async()=>{try{await coachApi.profile({displayName:name,slug,headline,bio,city,specializations:spec.split(",").map(x=>x.trim()).filter(Boolean),languages:p.languages,avatarUrl:avatar||null,acceptingOrders:accepting});setNotice(uiText("Профиль сохранён и отправлен на повторную модерацию"));refresh()}catch(e){setError(e instanceof Error?e.message:uiText("Ошибка"))}}}>{uiText("Сохранить")}</button></section>}
function title(tab:Tab){return ({overview:uiText("Рабочий обзор"),clients:uiText("Клиенты"),scheduling:uiText("Расписание"),services:uiText("Услуги и тарифы"),plans:uiText("Пакет клиентов"),site:uiText("Сайт коуча"),telegram:"Telegram",rewards:uiText("Награды"),profile:uiText("Профиль")} as const)[tab]}
function description(tab:Tab){return ({overview:uiText("Состояние практики и клиенты, которым сейчас нужна поддержка."),clients:uiText("Динамика, дневник, задания и обратная связь."),scheduling:uiText("Свободное время и предстоящие встречи внутри ORKEN."),services:uiText("Форматы ведения и консультаций для ваших клиентов."),plans:uiText("Места для клиентов, доступ которым оплачивает коуч."),site:uiText("Поддомен ORKEN или собственный домен."),telegram:uiText("Переход клиента в ORKEN через общего бота."),rewards:uiText("Модерируемые бонусы за внутреннюю валюту."),profile:uiText("Данные, которые видит пользователь в каталоге.")} as const)[tab]}
function statusLabel(status:string){return ({APPROVED:uiText("Профиль одобрен"),PENDING_REVIEW:uiText("На модерации"),REJECTED:uiText("Нужны исправления"),SUSPENDED:uiText("Доступ приостановлен"),DRAFT:uiText("Черновик")} as Record<string,string>)[status]||status}
function weekdayLabel(value:number){return ["",uiText("Понедельник"),uiText("Вторник"),uiText("Среда"),uiText("Четверг"),uiText("Пятница"),uiText("Суббота"),uiText("Воскресенье")][value]}
function minuteToTime(value:number){return `${String(Math.floor(value/60)).padStart(2,"0")}:${String(value%60).padStart(2,"0")}`}
function timeToMinute(value:string){const[hours,minutes]=value.split(":").map(Number);return hours*60+minutes}
function date(v:string){return new Intl.DateTimeFormat(getFormatLocale(),{dateStyle:"medium"}).format(new Date(v))}function money(a:number,c:string){return new Intl.NumberFormat(getFormatLocale(),{style:"currency",currency:c.toUpperCase(),maximumFractionDigits:0}).format(a/100)}
